import React, { useState, useEffect } from "react";

import Login from "./components/login";
import IncomeCategory from "./components/IncomeCategory";
import Questionnaire from "./components/Questionnaire";
import SpendingPriority from "./components/SpendingPriority";
import BudgetLimits from "./components/BudgetLimits";
import Preview from "./components/Preview";
import Dashboard from "./components/Dashboard";

function App() {

  const [user, setUser] = useState(null);
  const [step, setStep] = useState("login");

  const [data, setData] = useState({
    income: "",
    questionnaire: {},
    categories: [],
    limits: {}
  });

  // ✅ Load saved session
  useEffect(() => {
    const savedUser = JSON.parse(localStorage.getItem("user"));
    const savedData = JSON.parse(localStorage.getItem("onboardingData"));

    if (savedUser) {
      setUser(savedUser);

      if (savedData) {
        setData(savedData);
        setStep("dashboard"); // existing user → dashboard
      }
    }
  }, []);

  // ✅ Save data persistently
  useEffect(() => {
    localStorage.setItem("onboardingData", JSON.stringify(data));
  }, [data]);

  // ✅ LOGIN HANDLER
  const handleLogin = (userData, isNewUser = false) => {
    setUser(userData);

    if (isNewUser) {
      setStep("income");
    } else {
      setStep("dashboard");
    }
  };

  // ======================
  // PAGE FLOW
  // ======================

  if (!user) {
    return <Login onLogin={handleLogin} />;
  }

  if (step === "income") {
    return (
      <IncomeCategory
        onNext={(val) => {
          setData({ ...data, income: val });
          setStep("questionnaire");
        }}
      />
    );
  }

  if (step === "questionnaire") {
    return (
      <Questionnaire
        onNext={(val) => {
          setData({ ...data, questionnaire: val });
          setStep("spending");
        }}
        onBack={() => setStep("income")}
      />
    );
  }

  if (step === "spending") {
    return (
      <SpendingPriority
        selected={data.categories}
        onNext={(val) => {
          setData({ ...data, categories: val });
          setStep("budget");
        }}
        onBack={() => setStep("questionnaire")}
      />
    );
  }

  if (step === "budget") {
    return (
      <BudgetLimits
        categories={data.categories}
        limits={data.limits}
        onNext={(val) => {
          setData({ ...data, limits: val });
          setStep("preview");
        }}
        onBack={() => setStep("spending")}
      />
    );
  }

  if (step === "preview") {
    return (
      <Preview
        data={data}
        updateData={setData}
        onConfirm={() => {
          localStorage.setItem("onboardingData", JSON.stringify(data));
          setStep("dashboard");
        }}
        onBack={() => setStep("budget")}
      />
    );
  }

  return <Dashboard />;
}

export default App;
